def fit(g):
    H,W=len(g),len(g[0])
    known=[(i,j,v) for i in range(H) for j in range(W) if (v:=g[i][j])!=0]
    best=None
    for m in range(2,15):
        for a in (1,-1):
            for b in (1,-1):
                buckets={}
                for i,j,v in known:
                    buckets.setdefault((a*i+b*j)%m,[]).append(v)
                from collections import Counter
                table={k:Counter(vs).most_common(1)[0][0] for k,vs in buckets.items()}
                score=sum(1 for i,j,v in known if table[(a*i+b*j)%m]==v)
                if best is None or score>best[0]:
                    best=(score,m,a,b,table)
    return best
